ConsoleMode_SpellDescDB[5990] = { n="Nimble Reflexes", r="", d="Increases the caster's chance to parry by $s1% for $d.", t="Chance to parry increased by $s1%.", pt="Aumenta o dano de magias de Sombra em 3." }
ConsoleMode_SpellDescDB[5993] = { n="Enraging Bite", r="", d="Allows a hunter to teach $ghis:her; tamed bear the Enraging Bite ability. Enraging Bite reduces an enemy's resistance to physical attacks as well as drawing its attention.\nRequires: \nPet Level 13+", t="", pt="Ensina Mordida ao urso: -resist físico e atrai. Requer: pet nv 13+." }
ConsoleMode_SpellDescDB[5994] = { n="Growl of Fortitude", r="", d="Allows a hunter to teach $ghis:her; tamed bear the Growl of Fortitude ability. Growl of Fortitude increases the maximum health of the bear.\nRequires: \nPet Level 22+", t="", pt="Ensina Rugido ao urso: +vida máx do urso. Requer: pet nv 22+." }
ConsoleMode_SpellDescDB[5995] = { n="Roar of Fortitude", r="", d="Allows a hunter to teach $ghis:her; tamed bear the Roar of Fortitude ability. Roar of Fortitude increases the maximum health of everyone in your party.\nRequires: \nPet Level 36+", t="", pt="Ensina Rugido ao urso: +vida máx do grupo. Requer: pet nv 36+." }
ConsoleMode_SpellDescDB[5996] = { n="Flight of the Peregrine", r="", d="Allows a hunter to teach $ghis:her; tamed bird the Flight of the Peregrine ability. Flight of the Peregrine increase the movement speed of the bird.\nRequires: \nPet Level 13+", t="", pt="Ensina Voo à ave: +velocidade. Requer: pet nv 13+." }
ConsoleMode_SpellDescDB[5997] = { n="Eye Peck", r="", d="Allows a hunter to teach $ghis:her; tamed bird the Eye Peck ability. Eye Peck causes an enemy to miss more often in combat.\nRequires: \nPet Level 22+", t="", pt="Ensina Bicada à ave: inimigo erra mais. Requer: pet nv 22+." }
ConsoleMode_SpellDescDB[5998] = { n="Pester", r="", d="Allows a hunter to teach $ghis:her; tamed bird the Pester ability. Pester greatly increases the attack speed of the bird at the cost of dealing less damage. Every successful attack while in this mode renders the target unable to cast spells for a short time.\nRequires: \nPet Level 36+", t="", pt="Ensina Importunar à ave: +velocidade -dano, silencia ao acertar. Requer: pet nv 36+." }
ConsoleMode_SpellDescDB[5999] = { n="Ferocity", r="", d="Allows a hunter to teach $ghis:her; tamed cat the Ferocity ability. Ferocity increases attack speed of the cat at the cost of receiving more damage when hit by phsical attacks.\nRequires: \nPet Level 13+", t="", pt="Ensina Ferocidade ao gato: +velocidade +dano recebido. Requer: pet nv 13+." }
ConsoleMode_SpellDescDB[6000] = { n="Open Wound", r="", d="Allows a hunter to teach $ghis:her; tamed cat the Open Wound ability. Open Wound deals physical damage over time to an enemy as well as increasing damage received by physical attacks for a short time.\nRequires: \nPet Level 36+", t="", pt="Ensina Ferida ao gato: dot físico e +dano recebido. Requer: pet nv 36+." }
ConsoleMode_SpellDescDB[6001] = { n="Tough Shell", r="Rank 1", d="Allows a hunter to teach $ghis:her; tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it's armor value when hit.\nRequires: \nPet Level 13+", t="", pt="Ensina Carapaça ao siri. Requer: pet nv 13+." }
ConsoleMode_SpellDescDB[6002] = { n="Tough Shell", r="Rank 2", d="Allows a hunter to teach $ghis:her; tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it's armor value when hit.\nRequires: \nPet Level 21+", t="", pt="Ensina Carapaça ao siri. Requer: pet nv 21+." }
ConsoleMode_SpellDescDB[6003] = { n="Tough Shell", r="Rank 3", d="Allows a hunter to teach $ghis:her; tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it's armor value when hit.\nRequires: \nPet Level 28+", t="", pt="Ensina Carapaça ao siri. Requer: pet nv 28+." }
ConsoleMode_SpellDescDB[6004] = { n="Tough Shell", r="Rank 4", d="Allows a hunter to teach $ghis:her; tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it's armor value when hit.\nRequires: \nPet Level 36+", t="", pt="Ensina Carapaça ao siri. Requer: pet nv 36+." }
ConsoleMode_SpellDescDB[6005] = { n="Tight Pinch", r="", d="Allows a hunter to teach $ghis:her; tamed crab the Tight Pinch ability.\nRequires: \nPet Level 22+", t="", pt="Ensina Aperto ao siri. Requer: pet nv 22+." }
ConsoleMode_SpellDescDB[6006] = { n="Clenched Pinchers", r="", d="Allows a hunter to teach $ghis:her; tamed crab the Clenched Pinchers ability. Clenched Pinchers holds an enemy in place while dealing physical damage over time to it. While holding the enemy, the crab will be unable to attack or perform any other actions.\nRequires: \nPet Level 36+", t="", pt="Ensina Pinças ao siri: segura com dot, sem atacar. Requer: pet nv 36+." }
ConsoleMode_SpellDescDB[6007] = { n="Quick Snap", r="", d="Allows a hunter to teach $ghis:her; tamed crocilisk the Quick Snap ability. Quick Snap gives your crocilisk a chance to counterattack when hit.\nRequires: \nPet Level 22+", t="", pt="Ensina Bote ao crocolisco: contra-ataca ao apanhar. Requer: pet nv 22+." }
ConsoleMode_SpellDescDB[6008] = { n="Consume Flesh", r="", d="Allows a hunter to teach $ghis:her; tamed crocilisk the Consume Flesh ability. Consume Flesh gives your crocilisk a chance to steal health from an enemy when attacking.\nRequires: \nPet Level 36+", t="", pt="Ensina Carne ao crocolisco: rouba vida ao atacar. Requer: pet nv 36+." }
ConsoleMode_SpellDescDB[6009] = { n="Bruise", r="Rank 1", d="Allows a hunter to teach $ghis:her; tamed gorilla the Bruise ability. Bruise gives your gorilla a chance to reduce the armor value of an enemy when attacking.\nRequires: \nPet Level 13+", t="", pt="Ensina Machucado ao gorila. Requer: pet nv 13+." }
ConsoleMode_SpellDescDB[6010] = { n="Bruise", r="Rank 2", d="Allows a hunter to teach $ghis:her; tamed gorilla the Bruise ability. Bruise gives your gorilla a chance to reduce the armor value of an enemy when attacking.\nRequires: \nPet Level 18+", t="", pt="Ensina Machucado ao gorila. Requer: pet nv 18+." }
ConsoleMode_SpellDescDB[6011] = { n="Bruise", r="Rank 3", d="Allows a hunter to teach $ghis:her; tamed gorilla the Bruise ability. Bruise gives your gorilla a chance to reduce the armor value of an enemy when attacking.\nRequires: \nPet Level +25", t="", pt="Ensina Machucado ao gorila. Requer: pet nv 25+." }
ConsoleMode_SpellDescDB[6012] = { n="Bruise", r="Rank 4", d="Allows a hunter to teach $ghis:her; tamed gorilla the Bruise ability. Bruise gives your gorilla a chance to reduce the armor value of an enemy when attacking.\nRequires: \nPet Level 32+", t="", pt="Ensina Machucado ao gorila. Requer: pet nv 32+." }
