ConsoleMode_SpellDescDB[6015] = { n="Quickness", r="", d="Allows a hunter to teach $ghis:her; tamed gorilla the Quickness ability. Quickness is an attack that can hit multiple enemies.\nRequires: \nPet Level 36+", t="", pt="Ensina Rapidez ao gorila: atinge vários. Requer: pet nv 36+." }
