ConsoleMode_SpellDescDB[12824] = { n="Polymorph", r="Rank 2", d="Transforms the enemy into a sheep, forcing it to wander around for up to $d.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.", t="Cannot attack or cast spells.  Increased regeneration.", pt="Transforma o inimigo em uma ovelha, forçando-o a vagar desnorteado por até $d s. Enquanto estiver vagando, a ovelha não pode atacar nem lançar feitiços, mas regenera vida muito rapidamente. Qualquer dano sofrido transformará o alvo de volta à sua forma normal. Apenas um alvo pode ser polimorfado por vez. Só funciona em Feras, Humanoides e Bichos." }
ConsoleMode_SpellDescDB[12825] = { n="Polymorph", r="Rank 3", d="Transforms the enemy into a sheep, forcing it to wander around for up to $d.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.", t="Cannot attack or cast spells.  Increased regeneration.", pt="Transforma o inimigo em uma ovelha, forçando-o a vagar desnorteado por até $d s. Enquanto estiver vagando, a ovelha não pode atacar nem lançar feitiços, mas regenera vida muito rapidamente. Qualquer dano sofrido transformará o alvo de volta à sua forma normal. Apenas um alvo pode ser polimorfado por vez. Só funciona em Feras, Humanoides e Bichos." }
