ConsoleMode_SpellDescDB[20154] = { n="Seal of Righteousness", r="Rank 1", d="Fills the Paladin with holy spirit for $d, granting each melee attack an additional $/87;s1 to $/25;s1 Holy damage.  Slower weapons cause more Holy damage per swing.  Only one Seal can be active on the Paladin at any one time.", t="Melee attacks cause an additional $/87;20187s3 to $/25;20187s3 Holy damage.", pt="Enche o Paladino de espírito sagrado por $d s: cada corpo a corpo +$s1 a $s2 Sagrado. Arma lenta bate mais. Um Selo por vez." }
