ConsoleMode_SpellDescDB[20162] = { n="Seal of the Crusader", r="Rank 2", d="Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20188d, increasing Holy damage taken by up to $20188s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", t="Melee attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.", pt="Enche o Paladino de cruzado por $d s: +$s1 de poder corpo a corpo e +$s2% de velocidade, menos dano. Um Selo por vez. Julgar por $d1 s: +$s3 Sagrado recebido; golpe renova. Um Julgamento por Paladino." }
ConsoleMode_SpellDescDB[20163] = { n="Seal of Fury", r="Rank 1", d="Fills the Paladin with divine fury for $d, allowing melee attacks to cause additional threat.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for $20183d, causing Holy damage spells cast on that enemy to generate additional threat.  Only one Judgement per Paladin can be active at any one time.", t="Melee attacks cause additional threat.", pt="Enche o Paladino de fúria por $d s: corpo a corpo gera ameaça. Um Selo por vez. Julgar por $d1 s: Sagrado gera ameaça. Um Julgamento por Paladino." }
ConsoleMode_SpellDescDB[20164] = { n="Seal of Justice", r="", d="Fills the Paladin with the spirit of justice for $d, giving each melee attack a chance to stun for $20170d.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for $20184d, preventing them from fleeing.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", t="Melee attacks have a chance to stun for $20170d.", pt="Selo $d s: corpo a corpo pode atordoar por $d1 s. Um Selo por vez. Julgar por $d2 s: sem fugir; golpes renovam. Um Julgamento por Paladino." }
ConsoleMode_SpellDescDB[20165] = { n="Seal of Light", r="Rank 1", d="Fills the Paladin with divine light for $d, giving each melee attack a chance to heal the Paladin for $20167s1.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for $20185d, granting melee attacks made against the judged enemy a chance of healing the attacker for $20267s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", t="Melee attacks have a chance to heal you for $20167s1.", pt="Enche o Paladino de luz por $d s: corpo a corpo pode curar $s1. Um Selo por vez. Julgar por $d1 s: golpe no julgado pode curar $s2; golpe renova. Um Julgamento por Paladino." }
ConsoleMode_SpellDescDB[20166] = { n="Seal of Wisdom", r="Rank 1", d="Fills the Paladin with divine wisdom for $d, giving each melee attack a chance to restore $20168s1 of the Paladin's mana.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for $20186d, granting attacks and spells used against the judged enemy a chance to restore $20268s1 mana to the attacker.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", t="Melee attacks have a chance to restore $20168s1 mana.", pt="Enche o Paladino de sabedoria por $d s: corpo a corpo pode dar $s1 de mana. Um Selo por vez. Julgar por $d1 s: golpe e magia no julgado pode dar $s2; golpe renova. Um Julgamento por Paladino." }
